                const products = productsRes.data;
                const catMap: Record<string, number> = {};
                products.forEach((p: any) => {
                    catMap[p.category] = (catMap[p.category] || 0) + 1;
                });
                setProductsByCategory(Object.entries(catMap).map(([category, count]) => ({ category, count })));

                const dbStats = await getDashboardStats();
                setStats(dbStats.stats);
                setChartData({
                    leadsOverTime: dbStats.leadsOverTime,
                    leadStatusData: dbStats.leadStatusData,
                    recentActivity: dbStats.recentActivity
                });
            } catch (err) {
                console.error("Dashboard stats error:", err);
            } finally {
                setIsLoading(false);
            }
        };
        fetchStats();
    }, []);

    // Memoize the chart colors and metric computations
    const { conversionRate, healthyStock, totalStatusValues, wonLeads } = useMemo(() => {
        const total = chartData.leadStatusData.reduce((sum: number, s: any) => sum + (s.value || 0), 0);
        const won = chartData.leadStatusData.find((s: any) => s.name === 'Won')?.value || 0;
        const conv = total > 0 ? Math.round((won / total) * 100) : 0;
        const health = stats.totalProducts > 0 ? Math.round(((stats.totalProducts - stats.lowStockCount) / stats.totalProducts) * 100) : 0;
        return { conversionRate: conv, healthyStock: health, totalStatusValues: total, wonLeads: won };
    }, [chartData.leadStatusData, stats.totalProducts, stats.lowStockCount]);

    const leadStatusColors = useMemo<Record<string, string>>(() => ({
        New: '#74b9ff', Contacted: '#a29bfe', Qualified: '#00cec9', Won: '#00b894', Lost: '#ff7675'
    }), []);
    
    const barColors = useMemo(() => ['#e84393', '#00cec9', '#fdcb6e', '#6c5ce7', '#74b9ff', '#00b894', '#e17055', '#a29bfe'], []);

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-[60vh]">
                <LoadingSpinner size="lg" />
            </div>
        );
    }

    // Quick access cards based on role
    const cards: { title: string; icon: React.ReactNode; link?: string; color: string }[] = [];
    if (user?.role === 'admin') {
        cards.push(
            { title: t('sidebar.users') || 'Users', icon: svgs.users, link: '/admin/users', color: '#6c5ce7' },
            { title: t('sidebar.settings'), icon: svgs.settings, link: '/settings', color: '#e17055' },
            { title: t('sidebar.logs'), icon: svgs.logs, link: '/logs', color: '#00cec9' },
            { title: t('sidebar.aiAssistant') || 'AI Assistant', icon: svgs.ai, link: '/chatbot', color: '#e84393' },
            { title: t('sidebar.aiTraining') || 'AI Training', icon: svgs.brain, link: '/chatbot-training', color: '#fdcb6e' },
        );
    } else if (user?.role === 'agent_commercial') {
        cards.push(
            { title: t('sidebar.myLeads') || 'My Leads', icon: svgs.target, link: '/leads', color: '#e84393' },
            { title: t('sidebar.customers'), icon: svgs.handshake, link: '/customers', color: '#00cec9' },
            { title: 'Products', icon: svgs.box, link: '/products', color: '#6c5ce7' },
            { title: 'Performance', icon: svgs.chart, color: '#fdcb6e' },
        );
    } else {
        cards.push(
            { title: 'Tickets', icon: svgs.ticket, color: '#fdcb6e' },
            { title: 'Customers', icon: svgs.user, link: '/customers', color: '#6c5ce7' },
            { title: 'Knowledge', icon: svgs.book, color: '#00cec9' },
            { title: 'Issues', icon: svgs.check, color: '#00b894' },
        );
    }

    const statItems = [
        { label: t('dashboard.totalLeads') || 'Total Leads', value: stats.totalLeads, icon: svgs.target, iconClass: 'magenta', trend: '+12%', trendDir: 'up' },
        { label: t('dashboard.products') || 'Products', value: stats.totalProducts, icon: svgs.box, iconClass: 'cyan', trend: '+5%', trendDir: 'up' },
        { label: t('dashboard.customers') || 'Customers', value: stats.totalCustomers, icon: svgs.users, iconClass: 'amber', trend: '+8%', trendDir: 'up' },
        { label: t('dashboard.lowStock') || 'Low Stock', value: stats.lowStockCount, icon: svgs.alert, iconClass: 'red', trend: stats.lowStockCount > 0 ? t('dashboard.attention') || 'Attention' : t('dashboard.ok') || 'OK', trendDir: stats.lowStockCount > 0 ? 'down' : 'up' },
    ];

    return (
        <motion.div 
            className="db-root"
            variants={containerVariants}
            initial="hidden"
            animate="show"
        >
            {/* ── Header ──────────────────────────────────── */}
            <motion.div variants={itemVariants} className="db-header">
                <div>
                    <h1 className="db-header-title">{t('dashboard.overview') || 'Overview'}</h1>
                    <p className="db-header-sub">{t('dashboard.welcomeBack') || 'Welcome back'}, {user?.name?.split(' ')[0]}</p>
                </div>
                <div className="db-date-badge">
                    {new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}
                </div>
            </motion.div>

            {/* ── Stat Cards ─────────────────────────────── */}
            <motion.div variants={itemVariants} className="db-stats-grid">
                {statItems.map((s, i) => (
                    <motion.div 
                        key={s.label} 
                        className="db-stat-card"
                        whileHover={hoverCardStyle}
                        whileTap={{ scale: 0.98 }}
                        style={{ '--accent-gradient': `linear-gradient(90deg, ${i === 0 ? '#e84393' : i === 1 ? '#00cec9' : i === 2 ? '#fdcb6e' : '#ff7675'}, transparent)` } as React.CSSProperties}
                    >
                        <div className={`db-stat-icon ${s.iconClass}`}>
                            <span>{s.icon}</span>
                        </div>
                        <div className="db-stat-info">
                            <div className="db-stat-label">{s.label}</div>
                            <div className="db-stat-value">{s.value}</div>
                            <span className={`db-stat-trend ${s.trendDir}`}>
                                {s.trendDir === 'up' ? '↑' : '↓'} {s.trend}
                            </span>
                        </div>
                    </motion.div>
                ))}
            </motion.div>

            {/* ── Main 3-Column Grid ─────────────────────── */}
            <motion.div variants={itemVariants} className="db-main-grid">
                {/* Left — Quick Access */}
                <div className="db-quick-access">
                    <div className="db-quick-title">{t('dashboard.quickAccess')}</div>
                    {cards.map((c) => {
                        const inner = (
                            <>
                                <span className="db-quick-dot" style={{ background: c.color }} />
                                <span>{c.title}</span>
                            </>
                        );
                        return c.link ? (
                            <Link key={c.title} to={c.link} className="db-quick-item">{inner}</Link>
                        ) : (
                            <div key={c.title} className="db-quick-item" style={{ opacity: 0.5, cursor: 'default' }}>{inner}</div>
                        );
                    })}
                </div>

                {/* Center — Gauges, Progress, Charts */}
                <div className="db-center">
                    {/* Gauges */}
                    <div className="db-gauges-row">
                        <motion.div whileHover={hoverCardStyle} className="db-gauge-card">
                            <RadialGauge value={conversionRate} color="#e84393" />
                            <div className="db-gauge-info">
                                <div className="db-gauge-label">{t('dashboard.leadConversion') || 'Lead Conversion'}</div>
                                <div className="db-gauge-detail">
                                    {t('dashboard.wonOutOfTotal', { won: wonLeads, total: totalStatusValues }) || `${wonLeads} won out of ${totalStatusValues} total leads in pipeline`}
                                </div>
                            </div>
                        </motion.div>
                        <motion.div whileHover={hoverCardStyle} className="db-gauge-card">
                            <RadialGauge value={healthyStock} color="#00cec9" />
                            <div className="db-gauge-info">
                                <div className="db-gauge-label">{t('dashboard.stockHealth') || 'Stock Health'}</div>
                                <div className="db-gauge-detail">
                                    {t('dashboard.productsRunningLow', { low: stats.lowStockCount, total: stats.totalProducts }) || `${stats.lowStockCount} products running low out of ${stats.totalProducts}`}
                                </div>
                            </div>
                        </motion.div>
                    </div>

                    {/* Lead Status Progress Bars */}
                    <motion.div whileHover={hoverCardStyle} className="db-progress-card">
                        <div className="db-progress-title">{t('dashboard.leadStatusDistribution') || 'Lead Status Distribution'}</div>
                        {chartData.leadStatusData.map((status: any) => (
                            <ProgressBar
                                key={status.name}
                                label={status.name}
                                value={status.value}
                                max={totalStatusValues}
                                color={leadStatusColors[status.name] || '#a29bfe'}
                            />
                        ))}
                    </motion.div>

                    {/* Charts */}
                    <div className="db-charts-row">
                        {/* Area Chart - Leads Over Time */}
                        <motion.div whileHover={hoverCardStyle} className="db-chart-card">
                            <div className="db-chart-title">
                                <span className="db-chart-dot" style={{ background: '#e84393' }} />
                                {t('dashboard.leadsOverTime') || 'Leads Over Time'}
                            </div>
                            <ResponsiveContainer width="100%" height={220}>
                                <AreaChart data={chartData.leadsOverTime}>
                                    <defs>
                                        <linearGradient id="leadGrad" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="0%" stopColor="#e84393" stopOpacity={0.3} />
                                            <stop offset="100%" stopColor="#e84393" stopOpacity={0} />
                                        </linearGradient>
                                    </defs>
                                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                                    <XAxis dataKey="month" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                                    <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                                    <Tooltip
                                        contentStyle={{ backgroundColor: '#1a1f35', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '10px', color: '#f1f5f9', fontSize: '12px' }}
                                    />
                                    <Area type="monotone" dataKey="leads" stroke="#e84393" strokeWidth={2.5} fill="url(#leadGrad)" dot={{ fill: '#e84393', r: 4, strokeWidth: 0 }} activeDot={{ r: 6, stroke: '#e84393', strokeWidth: 2 }} />
                                </AreaChart>
                            </ResponsiveContainer>
                        </motion.div>

                        {/* Bar Chart - Products by Category */}
                        <motion.div whileHover={hoverCardStyle} className="db-chart-card">
                            <div className="db-chart-title">
                                <span className="db-chart-dot" style={{ background: '#00cec9' }} />
                                {t('dashboard.productsByCategory') || 'Products by Category'}
                            </div>
                            <ResponsiveContainer width="100%" height={220}>
                                <BarChart data={productsByCategory.length > 0 ? productsByCategory : [{ category: 'No data', count: 0 }]}>
                                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                                    <XAxis dataKey="category" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                                    <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                                    <Tooltip
                                        contentStyle={{ backgroundColor: '#1a1f35', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '10px', color: '#f1f5f9', fontSize: '12px' }}
                                    />
                                    <Bar dataKey="count" radius={[6, 6, 0, 0]}>
                                        {(productsByCategory.length > 0 ? productsByCategory : [{ category: 'No data', count: 0 }]).map((_, i) => (
                                            <Cell key={i} fill={barColors[i % barColors.length]} />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </motion.div>
                    </div>
                </div>

                {/* Right Panel — Big Stats + Pie + Activity */}
                <div className="db-right-panel">
                    {/* Big Stat 1 */}
                    <motion.div whileHover={hoverCardStyle} className="db-big-stat-card">
                        <div className="db-big-stat-value" style={{ color: '#a29bfe' }}>{conversionRate}%</div>
                        <div className="db-big-stat-label">{t('dashboard.leadConversionRate') || 'Lead Conversion Rate'}</div>
                        <div className="db-big-stat-bars">
                            <div className="db-big-stat-bar-track">
                                <motion.div 
                                    className="db-big-stat-bar-fill" 
                                    initial={{ width: 0 }}
                                    animate={{ width: `${conversionRate}%` }}
                                    transition={{ duration: 1, delay: 0.5, ease: "easeOut" }}
                                    style={{ background: 'linear-gradient(90deg, #6c5ce7, #a29bfe)' }} 
                                />
                            </div>
                            <div className="db-big-stat-bar-track">
                                <motion.div 
                                    className="db-big-stat-bar-fill" 
                                    initial={{ width: 0 }}
                                    animate={{ width: `${Math.min(conversionRate + 15, 100)}%` }}
                                    transition={{ duration: 1, delay: 0.7, ease: "easeOut" }}
                                    style={{ background: 'linear-gradient(90deg, #00cec9, #74b9ff)' }} 
                                />
                            </div>
                        </div>
                    </motion.div>

                    {/* Big Stat 2 */}
                    <motion.div whileHover={hoverCardStyle} className="db-big-stat-card">
                        <div className="db-big-stat-value" style={{ color: '#00cec9' }}>{healthyStock}%</div>
                        <div className="db-big-stat-label">{t('dashboard.inventoryHealthScore') || 'Inventory Health Score'}</div>
                        <div className="db-big-stat-bars">
                            <div className="db-big-stat-bar-track">
                                <motion.div 
                                    className="db-big-stat-bar-fill" 
                                    initial={{ width: 0 }}
                                    animate={{ width: `${healthyStock}%` }}
                                    transition={{ duration: 1, delay: 0.5, ease: "easeOut" }}
                                    style={{ background: 'linear-gradient(90deg, #00b894, #00cec9)' }} 
                                />
                            </div>
                            <div className="db-big-stat-bar-track">
                                <motion.div 
                                    className="db-big-stat-bar-fill" 
                                    initial={{ width: 0 }}
                                    animate={{ width: `${Math.max(healthyStock - 10, 0)}%` }}
                                    transition={{ duration: 1, delay: 0.7, ease: "easeOut" }}
                                    style={{ background: 'linear-gradient(90deg, #e84393, #fd79a8)' }} 
                                />
                            </div>
                        </div>
                    </motion.div>

                    {/* Pie Chart */}
                    <motion.div whileHover={hoverCardStyle} className="db-pie-card">
                        <div className="db-pie-title">{t('dashboard.leadStatus') || 'Lead Status'}</div>
                        <ResponsiveContainer width="100%" height={180}>
                            <PieChart>
                                <Pie
                                    data={chartData.leadStatusData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={45}
                                    outerRadius={70}
                                    paddingAngle={3}
                                    dataKey="value"
                                >
                                    {chartData.leadStatusData.map((entry: any, index: number) => (
                                        <Cell key={`cell-${index}`} fill={entry.color || barColors[index % barColors.length]} />
                                    ))}
                                </Pie>
                                <Tooltip
                                    contentStyle={{ backgroundColor: '#1a1f35', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '10px', color: '#f1f5f9', fontSize: '12px' }}
                                />
                                <Legend
                                    formatter={(value: any) => <span style={{ color: '#94a3b8', fontSize: '11px', fontWeight: 500 }}>{value}</span>}
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    </motion.div>

                    {/* Recent Activity */}
                    <motion.div whileHover={hoverCardStyle} className="db-activity-card">
                        <div className="db-activity-title">{t('dashboard.recentActivity') || 'Recent Activity'}</div>
                        {chartData.recentActivity.slice(0, 5).map((a: any) => {
                            // Map the backend emojis to our frontend SVGs
                            const activityIcon = a.icon === '🎯' ? svgs.target : 
                                                 a.icon === '👤' ? svgs.user : 
                                                 a.icon === '🛒' ? svgs.box : 
                                                 svgs.activity;
                                                 
                            return (
                                <div key={a.id} className="db-activity-item">
                                    <span className="db-activity-icon" style={{ display: 'flex', alignItems: 'center' }}>
                                        {activityIcon}
                                    </span>
                                    <div className="db-activity-text">
                                        <div className="db-activity-action">{a.action}</div>
                                        <div className="db-activity-detail">{a.detail}</div>
                                    </div>
                                    <span className="db-activity-time">{a.time}</span>
                                </div>
                            );
                        })}
                    </motion.div>
                </div>
            </motion.div>

            {/* ── ML Dashboard ────────────────────────────── */}
            <motion.div variants={itemVariants} className="db-ml-section">
                <MLDashboard />
            </motion.div>
        </motion.div>
    );
});

export default Dashboard;

import React, { useState, useEffect, useCallback } from 'react';
import { useCRM, Lead } from '../context/CRMContext';
import KanbanBoard from '../components/leads/KanbanBoard';
import LeadForm from '../components/leads/LeadForm';
import Skeleton from '../components/common/Skeleton';

const getPaginationGroup = (current: number, last: number) => {
    const pages: (number | string)[] = [];
    if (last <= 7) {
        for (let i = 1; i <= last; i++) pages.push(i);
    } else {
        pages.push(1);
        if (current > 3) pages.push('...');
        const start = Math.max(2, current - 1);
        const end = Math.min(last - 1, current + 1);
        for (let i = start; i <= end; i++) pages.push(i);
        if (current < last - 2) pages.push('...');
        pages.push(last);
    }
    return pages;
};

const statusColors: Record<string, { bg: string; text: string; dot: string }> = {
    new: { bg: 'rgba(59, 130, 246, 0.1)', text: '#60a5fa', dot: '#3b82f6' },
    contacted: { bg: 'rgba(245, 158, 11, 0.1)', text: '#fbbf24', dot: '#f59e0b' },
    qualified: { bg: 'rgba(139, 92, 246, 0.1)', text: '#a78bfa', dot: '#8b5cf6' },
    converted: { bg: 'rgba(16, 185, 129, 0.1)', text: '#34d399', dot: '#10b981' },
};

const Leads: React.FC = () => {
    const {
        leads, leadsPagination, leadsLoading,
        fetchLeads, updateLeadStatus, convertLead, deleteLead, currentUser
    } = useCRM();
    const [view, setView] = useState<'list' | 'kanban'>('list');
    const [showForm, setShowForm] = useState(false);
    const [editingLead, setEditingLead] = useState<Lead | null>(null);
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [confirmAction, setConfirmAction] = useState<{ type: string; lead: Lead } | null>(null);

    const loadLeads = useCallback(() => {
        fetchLeads(1, { status: statusFilter, search });
    }, [fetchLeads, statusFilter, search]);

    useEffect(() => {
        loadLeads();
    }, [loadLeads]);

    const handleSearch = (value: string) => {
        setSearch(value);
    };

    const handleStatusFilter = (value: string) => {
        setStatusFilter(value);
    };

    const handlePageChange = (page: number) => {
        fetchLeads(page, { status: statusFilter, search });
    };

    const handleEdit = (lead: Lead) => {
        setEditingLead(lead);
        setShowForm(true);
    };

    const handleDelete = async () => {
        if (confirmAction?.lead) {
            const success = await deleteLead(confirmAction.lead.id);
            if (success) {
                setConfirmAction(null);
            }
        }
    };

    const handleConvert = async () => {
        if (confirmAction?.lead) {
            const success = await convertLead(confirmAction.lead.id);
            if (success) {
                setConfirmAction(null);
            }
        }
    };

    const handleFormClose = () => {
        setShowForm(false);
        setEditingLead(null);
    };

    return (
        <div className="animate-fade-in">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div className="flex items-center space-x-3">
                    {/* View toggle */}
                    <div className="flex rounded-xl overflow-hidden" style={{ border: '1px solid var(--border-subtle)' }}>
                        <button onClick={() => setView('list')}
                            className={`px-4 py-2 text-sm font-medium transition-all ${view === 'list' ? 'text-[var(--text-primary)]' : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'}`}
                            style={view === 'list' ? { background: 'linear-gradient(135deg, rgba(99, 102, 241, 0.3), rgba(139, 92, 246, 0.2))' } : {}}>
                            ☰ List
                        </button>
                        <button onClick={() => setView('kanban')}
                            className={`px-4 py-2 text-sm font-medium transition-all ${view === 'kanban' ? 'text-[var(--text-primary)]' : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'}`}
                            style={view === 'kanban' ? { background: 'linear-gradient(135deg, rgba(99, 102, 241, 0.3), rgba(139, 92, 246, 0.2))' } : {}}>
                            ▦ Kanban
                        </button>
                    </div>
                </div>

                <div className="flex items-center space-x-3 w-full md:w-auto">
                    <button onClick={() => { setEditingLead(null); setShowForm(true); }}
                        className="px-5 py-2.5 text-sm font-semibold text-white rounded-xl transition-all duration-200 hover:shadow-lg hover:shadow-indigo-500/25 w-full md:w-auto"
                        style={{ background: 'linear-gradient(135deg, #6366f1, #8b5cf6)' }}>
                        + Add Lead
                    </button>
                </div>
            </div>

            {/* Filters */}
            <div className="flex flex-col sm:flex-row gap-3 mb-6">
                <div className="relative flex-1 max-w-md">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--text-secondary)]">🔍</span>
                    <input
                        placeholder="Search by company or email..."
                        className="w-full pl-11 pr-4 py-2.5 rounded-xl border-0 text-sm text-[var(--text-primary)] placeholder-[var(--text-muted)] focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                        style={{ background: 'var(--bg-secondary)', border: '1px solid var(--border-subtle)' }}
                        value={search}
                        onChange={e => handleSearch(e.target.value)}
                    />
                </div>
                <select
                    className="px-4 py-2.5 rounded-xl text-sm text-[var(--text-secondary)] cursor-pointer outline-none focus:ring-2 focus:ring-indigo-500/50"
                    style={{ background: 'var(--bg-secondary)', border: '1px solid var(--border-subtle)' }}
                    value={statusFilter}
                    onChange={e => handleStatusFilter(e.target.value)}
                >
                    <option value="">All Statuses</option>
                    <option value="new">New</option>
                    <option value="contacted">Contacted</option>
                    <option value="qualified">Qualified</option>
                    <option value="converted">Converted</option>
                </select>
            </div>

            {/* Content */}
            {view === 'kanban' ? (
                leadsLoading ? (
                    <div className="flex justify-center py-20">
                        <div className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                    </div>
                ) : (
                    <KanbanBoard leads={leads} />
                )
            ) : (
                <div className="glass-card overflow-hidden animate-slide-in">
                    <table className="min-w-full">
                        <thead>
                            <tr style={{ borderBottom: '1px solid var(--border-subtle)' }}>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Company</th>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Contact</th>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Email</th>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Phone</th>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Status</th>
                                {currentUser?.role === 'admin' && (
                                    <th className="px-6 py-4 text-left text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Created By</th>
                                )}
                                <th className="px-6 py-4 text-right text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {leadsLoading ? (
                                Array.from({ length: 5 }).map((_, i) => (
                                    <tr key={`skel-${i}`} style={{ borderBottom: '1px solid var(--border-subtle)' }}>
                                        <td className="px-6 py-4"><Skeleton height={20} width="70%" /></td>
                                        <td className="px-6 py-4"><Skeleton height={20} width="60%" /></td>
                                        <td className="px-6 py-4"><Skeleton height={20} width="80%" /></td>
                                        <td className="px-6 py-4"><Skeleton height={20} width="60%" /></td>
                                        <td className="px-6 py-4"><Skeleton height={24} width="80px" borderRadius="12px" /></td>
                                        {currentUser?.role === 'admin' && (
                                            <td className="px-6 py-4"><Skeleton height={20} width="50%" /></td>
                                        )}
                                        <td className="px-6 py-4 flex justify-end gap-2 text-right">
                                            <Skeleton height={28} width="50px" borderRadius="8px" />
                                            <Skeleton height={28} width="60px" borderRadius="8px" />
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                leads.map((lead, idx) => (
                                    <tr key={lead.id}
                                        className="transition-colors hover:bg-[var(--bg-secondary)]"
                                        style={{ borderBottom: idx < leads.length - 1 ? '1px solid var(--border-subtle)' : 'none', animationDelay: `${idx * 30}ms` }}>
                                        <td className="px-6 py-4">
                                            <div className="text-sm font-semibold text-[var(--text-primary)]">{lead.company_name}</div>
                                        </td>
                                        <td className="px-6 py-4 text-sm text-[var(--text-secondary)]">{lead.contact_name}</td>
                                        <td className="px-6 py-4 text-sm text-[var(--text-secondary)]">{lead.email}</td>
                                        <td className="px-6 py-4 text-sm text-[var(--text-secondary)]">{lead.phone || '—'}</td>
                                        <td className="px-6 py-4">
                                            <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-semibold"
                                                style={{ background: statusColors[lead.status]?.bg, color: statusColors[lead.status]?.text }}>
                                                <span className="w-1.5 h-1.5 rounded-full mr-2" style={{ background: statusColors[lead.status]?.dot }}></span>
                                                {lead.status.charAt(0).toUpperCase() + lead.status.slice(1)}
                                            </span>
                                        </td>
                                        {currentUser?.role === 'admin' && (
                                            <td className="px-6 py-4 text-sm text-[var(--text-secondary)]">{lead.creator?.name || '—'}</td>
                                        )}
                                        <td className="px-6 py-4 text-right space-x-2">
                                            <button onClick={() => handleEdit(lead)}
                                                className="px-3 py-1.5 text-xs font-medium text-indigo-400 rounded-lg transition-all hover:bg-indigo-500/10">
                                                Edit
                                            </button>
                                            {lead.status === 'qualified' && (
                                                <button onClick={() => setConfirmAction({ type: 'convert', lead })}
                                                    className="px-3 py-1.5 text-xs font-medium text-emerald-400 rounded-lg transition-all hover:bg-emerald-500/10">
                                                    Convert
                                                </button>
                                            )}
                                            <button onClick={() => setConfirmAction({ type: 'delete', lead })}
                                                className="px-3 py-1.5 text-xs font-medium text-red-400 rounded-lg transition-all hover:bg-red-500/10">
                                                Delete
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            )}
                            {!leadsLoading && leads.length === 0 && (
                                <tr>
                                    <td colSpan={7} className="px-6 py-16 text-center text-[var(--text-secondary)]">
                                        <div className="text-4xl mb-3">🎯</div>
                                        <p className="font-medium">No leads found</p>
                                        <p className="text-sm mt-1">Try adjusting your filters or add a new lead</p>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Pagination */}
            {!leadsLoading && leadsPagination.last_page > 1 && (
                <div className="flex justify-between items-center mt-6">
                    <p className="text-sm text-[var(--text-secondary)]">
                        Showing {leads.length} of {leadsPagination.total} leads
                    </p>
                    <div className="flex items-center space-x-1">
                        {getPaginationGroup(leadsPagination.current_page, leadsPagination.last_page).map((page, i) => (
                            typeof page === 'number' ? (
                                <button key={i} onClick={() => handlePageChange(page)}
                                    className={`px-3 py-1.5 text-sm rounded-lg transition-all ${page === leadsPagination.current_page
                                        ? 'text-white font-semibold'
                                        : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)]'
                                        }`}
                                    style={page === leadsPagination.current_page ? { background: 'linear-gradient(135deg, #6366f1, #8b5cf6)' } : {}}>
                                    {page}
                                </button>
                            ) : (
                                <span key={i} className="px-2 py-1.5 text-[var(--text-secondary)]">...</span>
                            )
                        ))}
                    </div>
                </div>
            )}

            {/* Lead Form Modal */}
            {showForm && <LeadForm lead={editingLead} onClose={handleFormClose} />}

            {/* Confirm Dialog */}
            {confirmAction && (
                <div className="fixed inset-0 z-50 flex items-center justify-center animate-fade-in" style={{ background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(4px)' }}>
                    <div className="glass-card p-6 w-full max-w-sm mx-4 animate-slide-in">
                        <h3 className="text-lg font-bold text-[var(--text-primary)] mb-2">
                            {confirmAction?.type === 'delete' ? 'Delete Lead' : 'Convert Lead'}
                        </h3>
                        <p className="text-sm text-[var(--text-secondary)] mb-6">
                            {confirmAction?.type === 'delete'
                                ? `Are you sure you want to delete "${confirmAction?.lead.company_name}"? This action can be undone.`
                                : `Convert "${confirmAction?.lead.company_name}" to a customer? This will create a new customer record.`}
                        </p>
                        <div className="flex justify-end space-x-3">
                            <button onClick={() => setConfirmAction(null)}
                                className="px-4 py-2 text-sm font-medium text-[var(--text-secondary)] rounded-xl hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)] transition-all">
                                Cancel
                            </button>
                            <button onClick={confirmAction?.type === 'delete' ? handleDelete : handleConvert}
                                className="px-4 py-2 text-sm font-semibold text-white rounded-xl transition-all"
                                style={{ background: confirmAction?.type === 'delete' ? '#ef4444' : 'linear-gradient(135deg, #10b981, #059669)' }}>
                                {confirmAction?.type === 'delete' ? 'Delete' : 'Convert'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Leads;

import React, { useState, FormEvent } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Profile: React.FC = () => {
    const { user, updateProfile } = useAuth();

    const [name, setName] = useState(user?.name ?? '');
    const [email, setEmail] = useState(user?.email ?? '');
    const [password, setPassword] = useState('');
    const [passwordConfirmation, setPasswordConfirmation] = useState('');
    const [success, setSuccess] = useState<string | null>(null);
    const [errors, setErrors] = useState<Record<string, string[]>>({});
    const [submitting, setSubmitting] = useState(false);

    if (!user) return null;

    const roleLabelMap: Record<string, string> = {
        admin: 'Administrator',
        agent_commercial: 'Commercial Agent',
        agent_sav: 'Support Agent',
    };

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        setErrors({});
        setSuccess(null);
        setSubmitting(true);

        const payload: Record<string, string> = {};
        if (name !== user.name) payload.name = name;
        if (email !== user.email) payload.email = email;
        if (password) {
            payload.password = password;
            payload.password_confirmation = passwordConfirmation;
        }

        if (Object.keys(payload).length === 0) {
            setSuccess('No changes to save.');
            setSubmitting(false);
            return;
        }

        try {
            await updateProfile(payload);
            setPassword('');
            setPasswordConfirmation('');
            setSuccess('Profile updated successfully!');
        } catch (err: any) {
            if (err.response?.data?.errors) {
                setErrors(err.response.data.errors);
            } else {
                setErrors({ general: [err.response?.data?.message || 'Update failed.'] });
            }
        } finally {
            setSubmitting(false);
        }
    };

    const firstError = (field: string) => errors[field]?.[0];

    return (
        <div className="profile-container">
            {/* Info Card */}
            <div className="profile-info-card">
                <div className="avatar">{user.name.charAt(0).toUpperCase()}</div>
                <h3>{user.name}</h3>
                <p>{user.email}</p>
                <span className={`role-pill role-${user.role}`}>{roleLabelMap[user.role]}</span>
            </div>

            {/* Edit Form */}
            <div className="profile-form-card">
                <h3>Edit Profile</h3>

                {success && <div className="alert alert-success">{success}</div>}
                {errors.general && <div className="alert alert-error">{errors.general[0]}</div>}

                <form onSubmit={handleSubmit} className="auth-form">
                    <div className="form-group">
                        <label htmlFor="prof-name">Full name</label>
                        <input id="prof-name" type="text" value={name} onChange={(e) => setName(e.target.value)} required />
                        {firstError('name') && <span className="field-error">{firstError('name')}</span>}
                    </div>

                    <div className="form-group">
                        <label htmlFor="prof-email">Email address</label>
                        <input id="prof-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
                        {firstError('email') && <span className="field-error">{firstError('email')}</span>}
                    </div>

                    <hr className="divider" />
                    <h4>Change Password</h4>

                    <div className="form-group">
                        <label htmlFor="prof-pass">New password</label>
                        <input id="prof-pass" type="password" placeholder="Leave blank to keep current" value={password} onChange={(e) => setPassword(e.target.value)} minLength={8} />
                        {firstError('password') && <span className="field-error">{firstError('password')}</span>}
                    </div>

                    <div className="form-group">
                        <label htmlFor="prof-pass-confirm">Confirm new password</label>
                        <input id="prof-pass-confirm" type="password" placeholder="Confirm new password" value={passwordConfirmation} onChange={(e) => setPasswordConfirmation(e.target.value)} minLength={8} />
                    </div>

                    <button type="submit" className="btn btn-primary" disabled={submitting}>
                        {submitting ? 'Saving…' : 'Save Changes'}
                    </button>
                </form>
            </div>
        </div>
    );
};

export default Profile;

import React, { useState, useEffect, FormEvent } from 'react';
import { Link } from 'react-router-dom';
import { useAuth, User } from '../../context/AuthContext';
import api from '../../services/api';

interface PaginatedUsers {
    data: User[];
    current_page: number;
    last_page: number;
    total: number;
}

const roleLabelMap: Record<string, string> = {
    admin: 'Administrator',
    agent_commercial: 'Commercial Agent',
    agent_sav: 'Support Agent',
};

const Users: React.FC = () => {
    const { user: currentUser } = useAuth();

    const [users, setUsers] = useState<PaginatedUsers | null>(null);
    const [page, setPage] = useState(1);
    const [loading, setLoading] = useState(true);

    // Modal state
    const [showModal, setShowModal] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [formName, setFormName] = useState('');
    const [formEmail, setFormEmail] = useState('');
    const [formPassword, setFormPassword] = useState('');
    const [formRole, setFormRole] = useState<string>('agent_commercial');
    const [formErrors, setFormErrors] = useState<Record<string, string[]>>({});
    const [formSubmitting, setFormSubmitting] = useState(false);

    // Delete confirmation
    const [deleteTarget, setDeleteTarget] = useState<User | null>(null);

    const fetchUsers = async (p: number) => {
        setLoading(true);
        try {
            const { data } = await api.get(`/users?page=${p}`);
            setUsers(data);
        } catch {
            // handled globally
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchUsers(page);
    }, [page]);

    // ── Open modal for create / edit ──
    const openCreate = () => {
        setEditingUser(null);
        setFormName('');
        setFormEmail('');
        setFormPassword('');
        setFormRole('agent_commercial');
        setFormErrors({});
        setShowModal(true);
    };

    const openEdit = (u: User) => {
        setEditingUser(u);
        setFormName(u.name);
        setFormEmail(u.email);
        setFormPassword('');
        setFormRole(u.role);
        setFormErrors({});
        setShowModal(true);
    };

    const handleSubmitUser = async (e: FormEvent) => {
        e.preventDefault();
        setFormErrors({});
        setFormSubmitting(true);

        try {
            if (editingUser) {
                // Update
                const payload: Record<string, string> = { name: formName, email: formEmail, role: formRole };
                if (formPassword) payload.password = formPassword;
                await api.put(`/users/${editingUser.id}`, payload);
            } else {
                // Create
                await api.post('/users', { name: formName, email: formEmail, password: formPassword, role: formRole });
            }
            setShowModal(false);
            fetchUsers(page);
        } catch (err: any) {
            if (err.response?.data?.errors) {
                setFormErrors(err.response.data.errors);
            } else {
                setFormErrors({ general: [err.response?.data?.message || 'Operation failed.'] });
            }
        } finally {
            setFormSubmitting(false);
        }
    };

    const handleDelete = async () => {
        if (!deleteTarget) return;
        try {
            await api.delete(`/users/${deleteTarget.id}`);
            setDeleteTarget(null);
            fetchUsers(page);
        } catch {
            // handled globally
        }
    };

    if (!currentUser) return null;

    return (
        <div style={{ height: '100%', overflowY: 'auto' }}>

            <div className="table-toolbar">
                <p className="table-count">{users?.total ?? 0} users total</p>
                <button className="btn btn-primary" onClick={openCreate}>+ Add User</button>
            </div>

            {loading ? (
                <div className="loading-screen"><div className="spinner" /><p>Loading users…</p></div>
            ) : (
                <>
                    <div className="table-wrapper">
                        <table className="data-table">
                            <thead>
                                <tr>
                                    <th>ID</th>
                                    <th>Name</th>
                                    <th>Email</th>
                                    <th>Role</th>
                                    <th>Created</th>
                                    <th>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {users?.data.map((u) => (
                                    <tr key={u.id}>
                                        <td>{u.id}</td>
                                        <td>{u.name}</td>
                                        <td>{u.email}</td>
                                        <td><span className={`role-pill role-${u.role}`}>{roleLabelMap[u.role]}</span></td>
                                        <td>{new Date(u.created_at).toLocaleDateString()}</td>
                                        <td className="actions-cell">
                                            <button className="btn btn-sm btn-outline" onClick={() => openEdit(u)}>Edit</button>
                                            <button className="btn btn-sm btn-danger" onClick={() => setDeleteTarget(u)}>Delete</button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    {/* Pagination */}
                    {users && users.last_page > 1 && (
                        <div className="pagination">
                            <button className="btn btn-sm btn-outline" disabled={page <= 1} onClick={() => setPage(page - 1)}>← Prev</button>
                            <span className="page-info">Page {users.current_page} of {users.last_page}</span>
                            <button className="btn btn-sm btn-outline" disabled={page >= users.last_page} onClick={() => setPage(page + 1)}>Next →</button>
                        </div>
                    )}
                </>
            )}

            {/* ── Create / Edit Modal ── */}
            {showModal && (
                <div className="modal-overlay" onClick={() => setShowModal(false)}>
                    <div className="modal-card" onClick={(e) => e.stopPropagation()}>
                        <h3>{editingUser ? 'Edit User' : 'Create User'}</h3>
                        {formErrors.general && <div className="alert alert-error">{formErrors.general[0]}</div>}
                        <form onSubmit={handleSubmitUser} className="auth-form">
                            <div className="form-group">
                                <label>Name</label>
                                <input type="text" value={formName} onChange={(e) => setFormName(e.target.value)} required />
                                {formErrors.name && <span className="field-error">{formErrors.name[0]}</span>}
                            </div>
                            <div className="form-group">
                                <label>Email</label>
                                <input type="email" value={formEmail} onChange={(e) => setFormEmail(e.target.value)} required />
                                {formErrors.email && <span className="field-error">{formErrors.email[0]}</span>}
                            </div>
                            <div className="form-group">
                                <label>Password {editingUser && '(leave blank to keep)'}</label>
                                <input type="password" value={formPassword} onChange={(e) => setFormPassword(e.target.value)} minLength={8} {...(!editingUser ? { required: true } : {})} />
                                {formErrors.password && <span className="field-error">{formErrors.password[0]}</span>}
                            </div>
                            <div className="form-group">
                                <label>Role</label>
                                <select value={formRole} onChange={(e) => setFormRole(e.target.value)}>
                                    <option value="admin">Administrator</option>
                                    <option value="agent_commercial">Commercial Agent</option>
                                    <option value="agent_sav">Support Agent</option>
                                </select>
                                {formErrors.role && <span className="field-error">{formErrors.role[0]}</span>}
                            </div>
                            <div className="modal-actions">
                                <button type="button" className="btn btn-ghost" onClick={() => setShowModal(false)}>Cancel</button>
                                <button type="submit" className="btn btn-primary" disabled={formSubmitting}>
                                    {formSubmitting ? 'Saving…' : editingUser ? 'Update' : 'Create'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* ── Delete Confirmation ── */}
            {deleteTarget && (
                <div className="modal-overlay" onClick={() => setDeleteTarget(null)}>
                    <div className="modal-card modal-sm" onClick={(e) => e.stopPropagation()}>
                        <h3>Confirm Delete</h3>
                        <p>Are you sure you want to delete <strong>{deleteTarget.name}</strong>? This action can be undone by an administrator.</p>
                        <div className="modal-actions">
                            <button className="btn btn-ghost" onClick={() => setDeleteTarget(null)}>Cancel</button>
                            <button className="btn btn-danger" onClick={handleDelete}>Delete</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Users;

import api from './api';

// ── Types ────────────────────────────────────────────────────────────────────

export interface ChurnPrediction {
    probability: number;
    risk_level: 'low' | 'medium' | 'high';
    features: {
        recency: number;
        frequency: number;
        monetary: number;
        loyalty_score: number;
    };
}

export interface LeadScore {
    score: number;
    priority: 'cold' | 'warm' | 'hot';
    features: Record<string, any>;
}

export interface CustomerSegment {
    cluster_id: number;
    segment: string;
    features: Record<string, any>;
}

export interface ProductRecommendation {
    product_id: number;
    score: number;
}

export interface RecommendationResult {
    customer_id: number;
    recommendations: ProductRecommendation[];
    note?: string;
}

export interface SentimentResult {
    sentiment: 'negative' | 'neutral' | 'positive';
    stars: number;
    confidence: number;
    text: string;
}

export interface ModelHealth {
    status: string;
    service: string;
    models: Record<string, boolean | string>;
}

export interface TrainingResult {
    status: string;
    results: Record<string, any>;
}

// ── API Client ───────────────────────────────────────────────────────────────

const ML_BASE = process.env.REACT_APP_ML_URL || 'http://localhost:8001';

const mlApi = {
    // Health
    health: () => fetch(`${ML_BASE}/health`).then(r => r.json()) as Promise<ModelHealth>,

    // Training
    trainAll: () => fetch(`${ML_BASE}/train/all`, { method: 'POST' }).then(r => r.json()) as Promise<TrainingResult>,

    // Churn
    predictChurn: (data: { recency: number; frequency: number; monetary: number; loyalty_score?: number }) =>
        fetch(`${ML_BASE}/predict/churn`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data),
        }).then(r => r.json()) as Promise<ChurnPrediction>,

    // Lead Scoring
    scoreLead: (data: { time_since_creation: number; status_encoded: number; has_phone?: number; has_email?: number; company_name_length?: number }) =>
        fetch(`${ML_BASE}/score/lead`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data),
        }).then(r => r.json()) as Promise<LeadScore>,

    // Segmentation
    segmentCustomer: (data: { recency: number; frequency: number; monetary: number; loyalty_score?: number }) =>
        fetch(`${ML_BASE}/segment/customer`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data),
        }).then(r => r.json()) as Promise<CustomerSegment>,

    // Recommendations
    recommend: (customerId: number, topK: number = 5) =>
        fetch(`${ML_BASE}/recommend/${customerId}?top_k=${topK}`).then(r => r.json()) as Promise<RecommendationResult>,

    // Sentiment
    analyzeSentiment: (text: string) =>
        fetch(`${ML_BASE}/analyze/sentiment`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ text }),
        }).then(r => r.json()) as Promise<SentimentResult>,

    analyzeSentimentBatch: (texts: string[]) =>
        fetch(`${ML_BASE}/analyze/sentiment/batch`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ texts }),
        }).then(r => r.json()) as Promise<{ results: SentimentResult[] }>,
};

export default mlApi;
